namespace PZ3D {
 static class SafehouseTransferFormatTests {
  static Type api;static int checks;
  static void Check(bool ok,string label){if(!ok)throw new Exception("FAIL "+label);checks++;}
  static object Call(string name,params object[] args){try{return api.GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static T Field<T>(object value,string name){return (T)value.GetType().GetField(name).GetValue(value);}
  static void Refuses(Action action,string label){bool refused=false;try{action();}catch(InvalidDataException){refused=true;}Check(refused,label);}
  internal static void Int(Stream s,int value){s.WriteByte((byte)(value>>24));s.WriteByte((byte)(value>>16));s.WriteByte((byte)(value>>8));s.WriteByte((byte)value);}
  internal static void Short(Stream s,short value){s.WriteByte((byte)(value>>8));s.WriteByte((byte)value);}
  internal static void Text(Stream s,string value){byte[] b=Encoding.UTF8.GetBytes(value);Short(s,(short)b.Length);s.Write(b,0,b.Length);}
  internal static uint Crc(byte[] b,int start){uint crc=0xffffffff;for(int i=start;i<b.Length;i++){crc^=b[i];for(int bit=0;bit<8;bit++)crc=(crc&1)!=0?(crc>>1)^0xedb88320:crc>>1;}return ~crc;}
  internal static byte[] DictionaryFixture(short[] ids,string[] fullTypes,bool incompatibleObjects=false,string[] objectNames=null,byte itemFlags=2){using(var s=new MemoryStream()){
   Int(s,1);Short(s,1000);s.WriteByte(1);Int(s,1);Int(s,0);string[] modules=fullTypes.Select(t=>t.Substring(0,t.LastIndexOf('.'))).Distinct().ToArray();Int(s,modules.Length);foreach(string m in modules)Text(s,m);Int(s,ids.Length);for(int i=0;i<ids.Length;i++){Short(s,ids[i]);s.WriteByte((byte)Array.IndexOf(modules,fullTypes[i].Substring(0,fullTypes[i].LastIndexOf('.'))));Text(s,fullTypes[i].Substring(fullTypes[i].LastIndexOf('.')+1));s.WriteByte(itemFlags);}Int(s,0);string[] objects=objectNames??new[]{incompatibleObjects?"DifferentObject":"IsoObject"};Int(s,objects.Length);for(int i=0;i<objects.Length;i++){s.WriteByte((byte)i);Text(s,objects[i]);}Int(s,1);Int(s,0);Text(s,"tiles_0");Int(s,0);Int(s,0);return s.ToArray();}}
  internal static byte[] ItemFixture(short id,byte[] prefix=null){using(var s=new MemoryStream()){byte[] fields=prefix??new byte[]{0};Int(s,7+fields.Length);Short(s,id);s.WriteByte(255);Int(s,123456);s.Write(fields,0,fields.Length);return s.ToArray();}}
  internal static byte[] Wrap(byte[] body,int version=249){byte[] raw=new byte[17+body.Length];using(var s=new MemoryStream(raw)){s.WriteByte(0);Int(s,version);Int(s,raw.Length);for(int i=0;i<8;i++)s.WriteByte(0);s.Write(body,0,body.Length);}uint crc=Crc(raw,17);raw[13]=(byte)(crc>>24);raw[14]=(byte)(crc>>16);raw[15]=(byte)(crc>>8);raw[16]=(byte)crc;return raw;}
  internal static byte[] ChunkFixture(short[] ids,int[] quantities){using(var s=new MemoryStream()){s.Write(new byte[]{0x55,0x22,0x77,0x33},0,4);Short(s,(short)ids.Length);for(int i=0;i<ids.Length;i++){Int(s,quantities[i]);byte[] item=ItemFixture(ids[i]);s.Write(item,0,item.Length);for(int n=1;n<quantities[i];n++)Int(s,123456+n);}return Wrap(s.ToArray());}}
  static byte[] Single(short id,byte[] prefix,int quantity=1){using(var s=new MemoryStream()){Short(s,1);Int(s,quantity);byte[] item=ItemFixture(id,prefix);s.Write(item,0,item.Length);for(int i=1;i<quantity;i++)Int(s,123456+i);return Wrap(s.ToArray());}}
  static byte[] World(short id){using(var s=new MemoryStream()){s.WriteByte(1);s.WriteByte(6);for(int i=0;i<5;i++)Int(s,0);byte[] item=ItemFixture(id);s.Write(item,0,item.Length);return s.ToArray();}}
  static byte[] ExtraPrefix(short id,bool invalidTag=false){using(var s=new MemoryStream()){s.WriteByte(64);Int(s,33);Int(s,1);s.WriteByte(0);Text(s,"nested");s.WriteByte(invalidTag?(byte)4:(byte)2);if(!invalidTag){Int(s,1);s.WriteByte(0);Text(s,"flag");s.WriteByte(3);s.WriteByte(1);}Int(s,1);Short(s,id);return s.ToArray();}}
  static byte[] Nested(short child){using(var s=new MemoryStream()){s.WriteByte(0);Int(s,77);Int(s,0);Short(s,1);Int(s,2);byte[] item=ItemFixture(child);s.Write(item,0,item.Length);Int(s,44);return s.ToArray();}}
  static byte[] AliasChunk(byte count){using(var s=new MemoryStream()){Short(s,2);Int(s,1);byte[] first=ItemFixture(1,new byte[]{0,0,count});s.Write(first,0,first.Length);Int(s,1);byte[] second=ItemFixture(1);s.Write(second,0,second.Length);return Wrap(s.ToArray());}}
  // Installed world249 HandWeapon.save writes an integer subclass header, then
  // count + WeaponPart.save (base InventoryItem, WITHOUT a size prefix).
  internal static byte[] WeaponWithPart(){using(var tail=new MemoryStream()){tail.WriteByte(0);Int(tail,1024);tail.WriteByte(1);byte[] part=ItemFixture(2);tail.Write(part,4,part.Length-4);return Single(1,tail.ToArray());}}
  // IsoTrap's exact world249 object segment: IsoObject class 19, no optional
  // base fields; fifteen four-byte values, two strings, present-byte, HandWeapon.
  internal static byte[] TrapWithWeapon(short weaponId=2){using(var body=new MemoryStream()){byte[] ordinary=ChunkFixture(new short[]{1},new[]{1});body.Write(ordinary,17,ordinary.Length-17);body.WriteByte(1);body.WriteByte(19);Int(body,-1);body.WriteByte(0);for(int i=0;i<15;i++)Int(body,0);Text(body,"");Text(body,"");body.WriteByte(1);byte[] weapon=ItemFixture(weaponId,new byte[]{0,0,0,0,0});body.Write(weapon,0,weapon.Length);return Wrap(body.ToArray());}}
  public static int Main(string[] args){try{if(args.Length==2&&args[0]=="--readonly-real"){ReadOnlyReal(args[1]);return 0;}Run();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
  static void ReadOnlyReal(string root){api=typeof(Engine).Assembly.GetType("PZ3D.SafehouseTransferFormat");var rows=new List<KeyValuePair<string,object>>();foreach(string world in Directory.GetDirectories(root)){string dictionary=Path.Combine(world,"WorldDictionary.bin");LauncherMaintenance.NoReparse(dictionary);if(File.Exists(dictionary))rows.Add(new KeyValuePair<string,object>(world,Call("Load",dictionary)));}int compatible=0,different=0;for(int i=0;i<rows.Count;i++)for(int j=i+1;j<rows.Count;j++){object plan=Call("Plan",rows[i].Value,rows[j].Value);if(Field<bool>(plan,"Supported")){compatible++;if(Field<int>(plan,"ChangedMappings")>0)different++;}}int total=0,accepted=0,known=0,unknown=0;long quantity=0;var reasons=new Dictionary<string,int>();var unknownReasons=new Dictionary<string,int>();foreach(var row in rows){object plan=Call("Plan",row.Value,row.Value);string map=Path.Combine(row.Key,"map");if(!Directory.Exists(map))continue;string[] files=Directory.GetFiles(map,"*.bin",SearchOption.AllDirectories).OrderByDescending(path=>new FileInfo(path).Length).Take(12).ToArray();int passed=0;foreach(string path in files){LauncherMaintenance.NoReparse(path);total++;string reason="";try{byte[] input=File.ReadAllBytes(path);object result=Call("TransformChunk",input,plan);byte[] output=Field<byte[]>(result,"Bytes");if(output!=null){if(!input.SequenceEqual(output))throw new Exception("Identity conversion changed bytes");passed++;accepted++;if(Field<bool>(result,"ItemCountKnown")){known++;quantity+=Field<long>(result,"ItemQuantity");}else{unknown++;string why=Field<string>(result,"CountUnknownReason");if(!unknownReasons.ContainsKey(why))unknownReasons[why]=0;unknownReasons[why]++;}}else reason=Field<string>(result,"UnsupportedReason");}catch(Exception ex){reason=ex.Message;}if(reason!=""){if(!reasons.ContainsKey(reason))reasons[reason]=0;reasons[reason]++;}}Console.WriteLine("READONLY world "+Path.GetFileName(row.Key)+": parsed dictionary EOF, supported chunks "+passed+"/"+files.Length);}Console.WriteLine("READONLY dictionaries="+rows.Count+", compatiblePairs="+compatible+", differingItemMappingPairs="+different+", supportedChunks="+accepted+"/"+total+", censusKnownChunks="+known+", censusUnknownChunks="+unknown+", knownQuantitySubtotal="+quantity);foreach(var pair in reasons)Console.WriteLine("REJECT "+pair.Value+": "+pair.Key);foreach(var pair in unknownReasons)Console.WriteLine("UNKNOWN COUNT "+pair.Value+": "+pair.Key);}
  public static void Run(){api=typeof(Engine).Assembly.GetType("PZ3D.SafehouseTransferFormat");Check(api!=null,"strict B42 transfer format implementation exists");string root=Path.Combine(Path.GetTempPath(),"ozl-transfer-format-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
   string a=Path.Combine(root,"source.bin"),b=Path.Combine(root,"target.bin");File.WriteAllBytes(a,DictionaryFixture(new short[]{1,2,3},new[]{"Base.Apple","Mod.Missing","Bag.Pack"}));File.WriteAllBytes(b,DictionaryFixture(new short[]{7,8},new[]{"Base.Apple","Bag.Pack"}));object source=Call("Load",a),target=Call("Load",b),plan=Call("Plan",source,target);Check(Field<int>(source,"ItemCount")==3&&Field<int>(source,"FormatVersion")==1,"binary dictionaries are parsed without a readable Lua sidecar");Check(Field<bool>(plan,"Supported")&&Field<string[]>(plan,"MissingTypes").SequenceEqual(new[]{"Mod.Missing"}),"differing item IDs with equal nonitem registries produce an explicit missing-type plan");
