   File.WriteAllBytes(Path.Combine(root,"trap-source.bin"),DictionaryFixture(new short[]{1,2},new[]{"Base.Apple","Base.PipeBomb"}));File.WriteAllBytes(Path.Combine(root,"trap-target.bin"),DictionaryFixture(new short[]{7,8},new[]{"Base.Apple","Base.PipeBomb"}));object trapSource=Call("Load",Path.Combine(root,"trap-source.bin")),trapPlan=Call("Plan",trapSource,Call("Load",Path.Combine(root,"trap-target.bin")));byte[] unclassified=TrapWithWeapon();object unclassifiedResult=Call("TransformChunk",unclassified,trapPlan);Check(Field<byte[]>(unclassifiedResult,"Bytes")==null&&Field<string>(unclassifiedResult,"UnsupportedReason").Contains("所属物体"),"a recognized ordinary item cannot authorize the unclassified standalone saveWithSize weapon inside a valid IsoTrap object segment");
