   byte[] stacked=Single(3,Nested(1),2);result=Call("TransformChunk",stacked,identityPlan);Check(Field<byte[]>(result,"Bytes")!=null&&!Field<bool>(result,"ItemCountKnown")&&Field<byte[]>(result,"Bytes").SequenceEqual(stacked),"identity mapping preserves stacked containers while marking their ambiguous quantities unknown");
   byte[] overlap=new byte[64];byte[] first=World(1);Array.Resize(ref first,57);first[22]=0;first[23]=0;first[24]=0;first[25]=31;Array.Copy(first,overlap,first.Length);byte[] second=World(1);Array.Copy(second,0,overlap,30,second.Length);result=Call("TransformChunk",Wrap(overlap),plan);Check(Field<byte[]>(result,"Bytes")==null&&Field<string>(result,"UnsupportedReason").Contains("重叠"),"partially overlapping item frames reject the entire chunk");
   foreach(byte aliasCount in new byte[]{1,2}){byte[] alias=AliasChunk(aliasCount);result=Call("TransformChunk",alias,identityPlan);Check(Field<byte[]>(result,"Bytes")!=null&&!Field<bool>(result,"ItemCountKnown")&&Field<byte[]>(result,"Bytes").SequenceEqual(alias),"identity copy keeps suffix aliases with opaque fields unchanged and marks quantity unknown");}
   result=Call("TransformChunk",Single(1,ExtraPrefix(1)),plan);Check(Field<byte[]>(result,"Bytes")!=null&&Field<long>(result,"ExtraReferences")==1,"supported nested Kahlua tables are skipped structurally before mapping extraItems");result=Call("TransformChunk",Single(1,ExtraPrefix(2)),plan);Check(Field<byte[]>(result,"Bytes")==null&&!string.IsNullOrEmpty(Field<string>(result,"UnsupportedReason")),"missing extraItems references refuse conversion rather than writing a null semantic reference");result=Call("TransformChunk",Single(1,ExtraPrefix(1,true)),plan);Check(Field<byte[]>(result,"Bytes")==null,"unknown Kahlua tags reject the affected chunk explicitly");
   using(var s=new MemoryStream()){s.WriteByte(64);Int(s,16);byte[] nested=Encoding.ASCII.GetBytes("WVER").Concat(new byte[]{0,0,0,249}).Concat(World(2)).ToArray();Int(s,nested.Length);s.Write(nested,0,nested.Length);byte[] corpse=Single(1,s.ToArray());result=Call("TransformChunk",corpse,plan);Check(Field<byte[]>(result,"Bytes")==null&&Field<string>(result,"UnsupportedReason").Contains("内嵌"),"WVER byteData can contain a corpse inventory and must refuse cross-ID remapping until parsed");result=Call("TransformChunk",corpse,identityPlan);Check(Field<byte[]>(result,"Bytes")!=null&&Field<byte[]>(result,"Bytes").SequenceEqual(corpse)&&!Field<bool>(result,"ItemCountKnown"),"identity mapping preserves embedded corpse data and reports quantity as unknown");}
